fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");
    assert_eq!(avgs.len(), n, "avgs must have the same length as vals_1");

    for i in 0..n {
        let v1 = vals_1[i];
        let v2 = vals_2[i];
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        avgs[i] = if c1 && c2 {
            // both true: integer average
            (v1 + v2) / 2
        } else if c1 {
            // only first is true
            v1
        } else if c2 {
            // only second is true
            v2
        } else {
            // by assumption this cannot happen
            unreachable!("At least one of conds_1[{}] or conds_2[{}] must be true", i, i);
        };
    }
}